#!/usr/bin/env python3
"""Pin and apply an explicitly imported classical theorem; no proof replay claim."""
from pathlib import Path
from itertools import product
import hashlib,html,json,re,time
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 started=time.monotonic();page=HERE/'moh-primary-account.html';assert sha(page)=='29591bbc082ec140b2dd85b9a34c891af021f336a9ac4cb7d84fc81690c01ed3';text=' '.join(html.unescape(re.sub('<[^>]+>',' ',page.read_text())).split());assert 'all three polynomials involved are of degree less than or equal to three. The result was affirmative' in text;assert 'if the degrees of the two polynomials in two variables are less than or equal to one hundred, then the conjecture is true' in text
 ledger=json.loads((ROOT/'MATH_STATUS.json').read_text());by={e['id']:e for e in ledger['entries']};gate=HERE/'validation.json';g=json.loads(gate.read_text());assert g['status']=='pass' and g['source_sha256']==sha(HERE/'verify.py') and g['proof_sha256']==sha(HERE/'PROOF.md');profiles=sorted((a,b,c) for a,b,c in product(range(1,8),repeat=3) if a>=b>=c and (a,b,c)<(7,6,4));small={tuple(p) for p in g['excluded_profiles']};cubic={p for p in profiles if p[0]<=3};closed=sorted(small|cubic);remaining=[p for p in profiles if p not in closed];assert len(profiles)==74 and len(cubic)==10 and cubic-small=={(3,3,3)} and len(closed)==48 and len(remaining)==26;assert all(p[0]>=4 and p[2]>=3 for p in remaining);quartic=[p for p in remaining if p[0]<=4];assert quartic==[(4,3,3),(4,4,3),(4,4,4)]
 source_review=ROOT/'jacobian-followup/cubic-reduction/classical-degree3-sources/screening.json';review=json.loads(source_review.read_text());assert review['reviewed_primary_abstract'] and not review['full_text_inspected'];assert review['doi']=='10.1016/S0022-4049(98)00040-1';assert by['F1']['state']=='proved' and by['KCUB3']['state']=='proved';base=ROOT/'jacobian-followup/cubic-reduction';wv=base/'cubic12-integer-witness.json';validation=base/'integer-validation12.json';v=json.loads(validation.read_text());assert v['status']=='pass' and v['witness_sha256']==sha(wv) and v['determinant_one'];assert by['KCUB3']['artifact_hash']=='sha256:'+sha(ROOT/by['KCUB3']['checker']);assert by['F1']['artifact_hash']=='sha256:'+sha(ROOT/by['F1']['checker']);assert (ROOT/by['F1']['canonical_source']).is_file()
 result=dict(status='pass',source_sha256=sha(Path(__file__)),proof_sha256=sha(HERE/'CLASSICAL_CUBIC_IMPORT.md'),primary_source_sha256=sha(page),primary_source_url='https://www.math.purdue.edu/~ttm/jacobian',primary_cubic_scope_phrase_checked=True,primary_plane100_scope_phrase_checked=True,vistoli_abstract_review_sha256=sha(source_review),vistoli_fulltext_inspected=False,imported_classical_theorem_independently_reproved=False,imported_classical_theorem_formalized=False,new_classical_theorem_imported=True,small_component_validation_sha256=sha(gate),total_profiles=74,all_cubic_profiles=sorted(cubic),additional_profiles=[(3,3,3)],excluded_profiles=closed,excluded_count=48,remaining_profiles=remaining,remaining_count=26,conditional_quartic_adds=quartic,conditional_quartic_remaining=23,quartic_theorem_imported=False,three_variable_ordinary_degree_interval=[4,7],ordinary_cubic_dimension_interval=[4,12],foundational_checker_sha256=sha(ROOT/by['F1']['checker']),foundational_proof_sha256=sha(ROOT/by['F1']['canonical_source']),ordinary_cubic_witness_sha256=sha(wv),ordinary_cubic_validation_sha256=sha(validation),normalized_support_interval=[10,48],positive_construction_bounds_changed=False,global_simplicity_minima_closed=False,scope='Explicit external classical3D degree<=3 Keller theorem import from exact primary author statement corroborated by published Vistoli abstract, not local proof reproduction. Exact profile/application checks only. Degree3D[4,7] and ordinary-cubic dimension[4,12] remain intervals; all global support/special-form minima remain open.',seconds=round(time.monotonic()-started,3));(HERE/'classical-validation.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n');print('PASS classical scope import:48 profiles excluded,26 remain;3D degree[4,7];ordinary-cubic dimension[4,12]; not a proof replay')
if __name__=='__main__':main()
